VALUES
((SELECT id FROM vocab_words WHERE lower(headword)=lower('halve')), 'Researchers found that regular exercise can halve the risk of heart disease.', '研究人员发现，规律锻炼可以减半心脏病的风险。', 'halve the risk', 'health', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('halve')), 'If you want to save money, you should halve your expenses every month.', '如果你想省钱，你应该每个月减半开支。', 'halve your expenses', 'daily_life', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('halve')), 'In order to meet the deadline, we need to halve the workload on this project.', '为了赶上截止日期，我们需要减半这个项目的工作量。', 'halve the workload', 'work', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('concentrated')), 'Many employees have concentrated their efforts on improving productivity this quarter.', '许多员工在这一季度专注于提高生产力。', 'concentrated effort', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('concentrated')), 'In chemical experiments, a concentrated solution is often used for better results.', '在化学实验中，通常使用浓缩溶液以获得更好的结果。', 'concentrated solution', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('concentrated')), 'The data was presented in a concentrated form to highlight key findings effectively.', '数据以集中形式呈现，以有效突出关键发现。', 'concentrated form', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('unpaid')), 'Many students seek unpaid internships to gain valuable experience in their field.', '许多学生寻求未支付的实习，以获得他们所在领域的宝贵经验。', 'unpaid internships', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('unpaid')), 'Homeowners should address any unpaid bills to avoid service interruptions.', '房主应处理任何未支付的账单，以避免服务中断。', 'unpaid bills', 'daily_life', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('unpaid')), 'The company faced severe consequences due to unpaid debts and financial mismanagement.', '由于未支付的债务和财务管理不善，该公司面临严重后果。', 'unpaid debts', 'news', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('vector')), 'In physics, the velocity vector indicates both speed and direction of an object.', '在物理学中，速度矢量指示物体的速度和方向。', 'velocity vector', 'science_tech', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('vector')), 'Data vectors are essential for machine learning algorithms to process information effectively.', '数据矢量对于机器学习算法有效处理信息至关重要。', 'data vector', 'work', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('vector')), 'Understanding the force vector is crucial for solving physics problems involving forces acting at angles.', '理解力矢量对于解决涉及角度作用力的物理问题至关重要。', 'force vector', 'education', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('grassy')), 'Wild animals often roam in grassy fields during the summer months.', '野生动物常常在夏季的草地上游荡。', 'grassy fields', 'environment', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('grassy')), 'Children love to play in the grassy areas of the park on sunny days.', '孩子们喜欢在阳光明媚的日子里，在公园的草地上玩耍。', 'grassy areas', 'daily_life', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('grassy')), 'Hikers enjoyed the breathtaking views from the grassy slopes of the mountain.', '徒步旅行者在山的草坡上欣赏到了令人叹为观止的景色。', 'grassy slopes', 'travel', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('stairway')), 'Many believe that the stairway to heaven is a metaphor for spiritual enlightenment.', '许多人相信，通往天堂的楼梯是精神启蒙的隐喻。', 'stairway to heaven', 'culture', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('stairway')), 'This hotel provides stairway access to all guest rooms, ensuring convenience.', '这家酒店提供楼梯通道到所有客房，以确保便利。', 'stairway access', 'travel', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('stairway')), 'Students studied the stairway design as part of their architectural coursework.', '学生们在建筑课程中学习楼梯设计。', 'stairway design', 'education', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hearty')), 'Friends shared a hearty laughter as they reminisced about old times.', '朋友们在回忆往事时，开怀大笑。', 'hearty laughter', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hearty')), 'After a long hike, they enjoyed a hearty meal to replenish their energy.', '长途徒步后，他们享用了一顿丰盛的餐点以补充能量。', 'hearty meal', 'health', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hearty')), 'The guests received a hearty welcome at the traditional ceremony held in their honor.', '客人在为他们举行的传统仪式上受到了热情的欢迎。', 'hearty welcome', 'culture', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('snail')), 'Garden snails are often found munching on plants in backyards.', '花园蜗牛常常在后院的植物上啃食。', 'garden snail', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('snail')), 'The project has been moving at a snail pace due to various delays.', '由于各种延误，项目进展缓慢。', 'snail pace', 'work', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('snail')), 'Researchers discovered a new species of sea snail in the coral reef.', '研究人员在珊瑚礁中发现了一种新的海蜗牛物种。', 'sea snail', 'science_tech', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('winding')), 'Driving along a winding road can be both exciting and challenging.', '沿着蜿蜒的道路驾驶既刺激又具挑战性。', 'winding road', 'travel', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('winding')), 'The winding river flows gently through the valley, creating stunning landscapes.', '蜿蜒的河流轻柔地穿过山谷，形成了迷人的风景。', 'winding river', 'environment', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('winding')), 'She enjoyed walking on the winding path that led to the garden.', '她喜欢走那条通往花园的曲折小路。', 'winding path', 'daily_life', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('likeness')), 'Her striking likeness to the actress made everyone do a double take.', '她与那位女演员的惊人相似让所有人都多看了一眼。', 'striking likeness', 'culture', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('likeness')), 'There is a clear family likeness that spans several generations in the photos.', '照片中几代人之间明显存在家族相似性。', 'family likeness', 'daily_life', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('likeness')), 'Many religious texts emphasize the importance of striving for the likeness of Christ in daily life.', '许多宗教文本强调在日常生活中追求基督形象的重要性。', 'likeness of Christ', 'education', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hysteria')), 'Reports of mass hysteria spread quickly among the crowd during the event.', '在事件期间，关于群众歇斯底里的报告迅速在现场传播。', 'mass hysteria', 'news', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hysteria')), 'Public hysteria over the new legislation was evident in social media discussions.', '公众对新立法的歇斯底里在社交媒体讨论中显而易见。', 'hysteria over', 'culture', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hysteria')), 'Scholars analyze the hysteria surrounding the pandemic and its impact on society.', '学者们分析与疫情相关的歇斯底里及其对社会的影响。', 'hysteria surrounding', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('polymer')), 'Synthetic polymers are widely used in various industries for their versatility.', '合成聚合物在多个行业中因其多功能性而被广泛使用。', 'synthetic polymers', 'science_tech', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('polymer')), 'Natural polymers can be found in many biological materials, such as cellulose and proteins.', '天然聚合物可以在许多生物材料中找到，例如纤维素和蛋白质。', 'natural polymers', 'environment', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('polymer')), 'Biodegradable polymers are essential for reducing plastic waste in our environment.', '可生物降解聚合物对于减少我们环境中的塑料废物至关重要。', 'biodegradable polymers', 'daily_life', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('necessitate')), 'Changes in regulations will necessitate action from all departments involved.', '法规的变化将使所有相关部门必须采取行动。', 'necessitate action', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('necessitate')), 'The unexpected results may necessitate further investigation into the initial hypothesis.', '意外的结果可能会使对初始假设进行进一步调查成为必要。', 'necessitate further investigation', 'academic', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('necessitate')), 'New projects often necessitate additional resources to ensure successful implementation.', '新项目通常需要额外的资源以确保成功实施。', 'necessitate additional resources', 'science_tech', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('obese')), 'An increasing number of children are becoming obese in urban areas.', '城市地区越来越多的儿童变得肥胖。', 'obese population', 'health', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('obese')), 'Researchers are studying the effects of diet on obese individuals'' health.', '研究人员正在研究饮食对肥胖个体健康的影响。', 'obese individuals', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('obese')), 'A recent report highlighted the growing number of obese adults in the country.', '最近一份报告强调了该国肥胖成年人数量的增长。', 'obese adults', 'news', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('monstrous')), 'Such monstrous behavior at the event shocked everyone in attendance.', '在活动中如此可怕的行为令在场的每个人感到震惊。', 'monstrous behavior', 'culture', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('monstrous')), 'Many activists condemned the monstrous injustice faced by marginalized communities.', '许多活动分子谴责边缘化群体所遭受的可怕不公。', 'monstrous injustice', 'news', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('monstrous')), 'Researchers discovered a monstrous creature lurking in the depths of the ocean.', '研究人员在海洋深处发现了一种可怕的生物。', 'monstrous creature', 'science_tech', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('pantry')), 'They organized the kitchen pantry to maximize space and efficiency.', '他们整理了厨房的食品储藏室，以最大化空间和效率。', 'kitchen pantry', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('pantry')), 'The company installed new pantry shelves to accommodate additional supplies.', '公司安装了新的食品储藏室货架，以容纳更多的物资。', 'pantry shelves', 'work', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('pantry')), 'Researchers analyzed the nutritional value of common pantry items used in households.', '研究人员分析了家庭中常见食品储藏室物品的营养价值。', 'pantry items', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('regiment')), 'Many soldiers from the regiment were deployed to assist in humanitarian efforts.', '该团的许多士兵被派遣去协助人道主义工作。', 'regiment of soldiers', 'news', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('regiment')), 'Effective leadership is crucial for the success of any regiment command structure.', '有效的领导对任何军团指挥结构的成功至关重要。', 'regiment command', 'work', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('regiment')), 'Students participating in regiment training often develop discipline and teamwork skills.', '参加军团训练的学生通常会培养纪律性和团队合作技能。', 'regiment training', 'education', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('chatter')), 'During breaks, students often engage in chatter among themselves about various topics.', '在课间，学生们常常就各种话题进行闲聊。', 'chatter among students', 'education', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('chatter')), 'The cheerful chatter of birds filled the air as spring arrived, bringing life back to the trees.', '随着春天的到来，鸟儿愉快的喧哗声充满了空气，给树木带来了生机。', 'chatter of birds', 'environment', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('chatter')), 'Many people enjoy the instant chatter on social media platforms, sharing thoughts and opinions.', '许多人喜欢在社交媒体平台上进行即时闲聊，分享他们的想法和观点。', 'chatter on social media', 'daily_life', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('wrench')), 'She tried to wrench open the rusty metal door but struggled.', '她试图猛拉打开生锈的铁门，但很费劲。', 'wrench open', 'daily_life', 0),
