((SELECT id FROM vocab_words WHERE lower(headword)=lower('snore')), 'People often complain when someone snores loudly during the night.', '当有人在夜间打鼾时，人们常常会抱怨。', 'snore loudly', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('snore')), 'Many adults snore in their sleep, which can indicate sleep apnea.', '许多成年人在睡眠中打鼾，这可能是睡眠呼吸暂停的迹象。', 'snore in their sleep', 'health', 1),
