((SELECT id FROM vocab_words WHERE lower(headword)=lower('extraction')), 'Researchers conducted DNA extraction to analyze genetic material from the samples.', '研究人员进行了 DNA 提取，以分析样本中的遗传物质。', 'DNA extraction', 'science_tech', 0),
