((SELECT id FROM vocab_words WHERE lower(headword)=lower('hydraulic')), 'Engineers designed a hydraulic system to increase the machinery''s efficiency.', '工程师设计了一个液压系统，以提高机器的效率。', 'hydraulic system', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hydraulic')), 'The experiment demonstrated how hydraulic pressure can lift heavy objects easily.', '实验展示了液压压力如何轻松提升重物。', 'hydraulic pressure', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hydraulic')), 'Many vehicles rely on hydraulic fluids to operate their braking systems effectively.', '许多车辆依靠液压液有效操作其制动系统。', 'hydraulic fluids', 'daily_life', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('principally')), 'Researchers are principally focused on the impact of climate change on biodiversity.', '研究人员主要关注气候变化对生物多样性的影响。', 'principally focused on', 'academic', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('principally')), 'The decline in enrollment is principally due to recent budget cuts at the university.', '入学人数下降主要是由于大学最近的预算削减。', 'principally due to', 'news', 1),
