((SELECT id FROM vocab_words WHERE lower(headword)=lower('paradoxically')), 'Many students find that paradoxically, learning a second language simplifies their understanding of their native tongue.', '许多学生发现，矛盾的是，学习第二语言使他们对母语的理解变得更加简单。', 'paradoxically, it simplifies the process', 'education', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('paradoxically')), 'Despite failing the project, he was paradoxically praised for his innovative approach to problem-solving.', '尽管项目失败，矛盾的是，他因创新问题解决方法而受到赞扬。', 'paradoxically, he was praised for his mistakes', 'work', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('electrode')), 'Proper electrode placement is essential for accurate cardiac monitoring during surgeries.', '正确的电极放置对手术期间的心脏监测至关重要。', 'electrode placement', 'health', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('electrode')), 'Researchers are developing new materials to improve the electrode surface for better conductivity.', '研究人员正在开发新材料以改善电极表面，从而提高导电性。', 'electrode surface', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('electrode')), 'The study focuses on the electrode measurement techniques used in biochemical sensors.', '该研究着重于生化传感器中使用的电极测量技术。', 'electrode measurement', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('shortfall')), 'Many organizations are facing a significant shortfall in funding for their projects.', '许多组织面临着项目资金的重大短缺。', 'shortfall in funding', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('shortfall')), 'The company reported a shortfall in revenue due to decreased sales this quarter.', '该公司因本季度销售下降而报告了收入不足。', 'shortfall in revenue', 'news', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('shortfall')), 'Researchers are concerned about the shortfall in resources needed for their experiments.', '研究人员对实验所需资源的短缺表示担忧。', 'shortfall in resources', 'science_tech', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hearth')), 'Families often gather around the open hearth during cold winter evenings.', '家人们常在寒冷的冬夜围坐在开放的炉床旁。', 'open hearth', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hearth')), 'The concept of hearth and home symbolizes comfort and security in many cultures.', '炉床与家庭的概念在许多文化中象征着安逸和安全。', 'hearth and home', 'culture', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('hearth')), 'Workers during the industrial era relied on the hearth fire for metalworking processes.', '工业时代的工人依靠炉床火焰进行冶金加工。', 'hearth fire', 'work', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('bribe')), 'Investigators found evidence that criminals sought to bribe officials to avoid prosecution.', '调查人员发现证据，犯罪分子企图贿赂官员以逃避起诉。', 'to bribe officials', 'news', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('bribe')), 'Employees caught accepting a bribe faced immediate termination from the company.', '被发现接受贿赂的员工将立即被解雇。', 'to accept a bribe', 'work', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('bribe')), 'Research indicates that bribes can lead to significant levels of corruption within governments.', '研究表明，贿赂可能导致政府内部出现严重腐败。', 'bribes can lead to corruption', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('induction')), 'Researchers are exploring the effects of electromagnetic induction on energy efficiency.', '研究人员正在探索电磁感应对能效的影响。', 'electromagnetic induction', 'science_tech', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('induction')), 'Every year, the school hosts an induction ceremony for new students and their families.', '每年，学校都会为新生及其家庭举办入学仪式。', 'induction ceremony', 'education', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('induction')), 'The induction process for new employees includes comprehensive training and orientation.', '新员工的入职流程包括全面的培训和指导。', 'induction process', 'work', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('skyscraper')), 'Visitors marveled at the tall skyscraper dominating the city skyline.', '游客们惊叹于主导城市天际线的高摩天大楼。', 'tall skyscraper', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('skyscraper')), 'Many companies prefer to rent space in an office skyscraper for better visibility.', '许多公司更喜欢在摩天大楼内租用办公空间，以提高可见度。', 'office skyscraper', 'work', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('skyscraper')), 'The city council announced plans for a new skyscraper to address housing needs.', '市议会宣布计划兴建一座新的摩天大楼，以满足住房需求。', 'new skyscraper', 'news', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('biased')), 'Journalists must strive to avoid presenting a biased opinion in their reports.', '记者必须努力避免在报道中表现出偏见的观点。', 'biased opinion', 'news', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('biased')), 'Researchers criticized the biased approach employed in the study''s methodology.', '研究人员批评了该研究方法中采用的偏向性方法。', 'biased approach', 'academic', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('biased')), 'Receiving biased information can lead to misunderstandings and poor decision-making.', '获取偏见的信息可能导致误解和不良决策。', 'biased information', 'daily_life', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('unreliable')), 'Many journalists avoid citing unreliable sources in their articles to maintain credibility.', '许多记者在文章中避免引用不可靠的来源，以保持信誉。', 'unreliable sources', 'news', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('unreliable')), 'Researchers must discard any unreliable data that could skew the results of their experiments.', '研究人员必须丢弃任何可能影响实验结果的不可靠数据。', 'unreliable data', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('unreliable')), 'Using unreliable equipment can lead to costly mistakes in any production line.', '使用不可靠的设备可能导致生产线上的昂贵错误。', 'unreliable equipment', 'work', 2),
